package jp.tapmarker;
import java.util.*;
/** Two independent ink masks from the supplied 2026-10-27 farm reward. */
final class FarmRewardReference {
 private static final String[] DATA={
  "",
  "",
  "",
 };
 static void addTo(List<float[]> refs){for(String text:DATA){if(text.length()!=512)throw new IllegalStateException("farm reward mask");float[] ref=new float[1536];for(int i=0;i<text.length();i++){int count=text.charAt(i)-'0';if(count<0||count>9)throw new IllegalStateException("farm reward mask value");float v=count/9f;ref[i*3]=v;ref[i*3+1]=v;ref[i*3+2]=v;}refs.add(ref);}}
 private FarmRewardReference(){}
}
